import { NextResponse } from "next/server";
import { handleOAuthCallback } from "@/infra/google-calendar/oauth";

export async function GET(request: Request) {
  const { searchParams, origin } = new URL(request.url);
  const code = searchParams.get("code");
  const state = searchParams.get("state");
  const error = searchParams.get("error");

  if (error) {
    console.error("[google-calendar] OAuth error:", error);
    return NextResponse.redirect(`${origin}/?error=google_calendar_denied`);
  }

  if (!code || !state) {
    return new Response("Bad request", { status: 400 });
  }

  try {
    await handleOAuthCallback(code, state);
    return NextResponse.redirect(`${origin}/?connected=google_calendar`);
  } catch (err: unknown) {
    console.error("[google-calendar] callback error", err);
    return NextResponse.redirect(`${origin}/?error=google_calendar_callback`);
  }
}

adapters.prisma:
import { db } from "@/lib/db";
import type { GoogleTokens } from "./token-store";

export const adapter = {
  getTokens: async (userId: string): Promise<GoogleTokens | null> => {
    const record = await db.googleCalendarToken.findUnique({
      where: { userId },
    });
    if (!record) return null;
    return {
      accessToken: record.accessToken,
      refreshToken: record.refreshToken,
      expiresAt: record.expiresAt.getTime(),
    };
  },

  saveTokens: async (userId: string, tokens: GoogleTokens): Promise<void> => {
    await db.googleCalendarToken.upsert({
      where: { userId },
      update: {
        accessToken: tokens.accessToken,
        refreshToken: tokens.refreshToken,
        expiresAt: new Date(tokens.expiresAt),
      },
      create: {
        userId,
        accessToken: tokens.accessToken,
        refreshToken: tokens.refreshToken,
        expiresAt: new Date(tokens.expiresAt),
      },
    });
  },
};

